"""Sokoban with the target hidden (VAGEN's simulator: gym_sokoban's room generator and dynamics, 6 x 6 with one box, generated by
VAGEN's own code in benchmarks/vagen, vagen/envs/sokoban; MIT) for the RLVB (EM) trainer. The rooms are VAGEN's: its
seeding, its shortest-solution search, its retry rule, its min_solution_steps band (BAND, the rooms whose own solution takes 1 to 5
actions) and its map partition by the room's hash (training: the 'train' partition, validation: 'eval', test: none, as in VAGEN's
training, validation and evaluation configs); the test seeds are VAGEN's evaluation seeds, and training and validation never use a
test room. Our hidden version: the target square is drawn evenly from the cells the box can be pushed to (the generator's own target
is not tractable: it plays backwards from it), and it is hidden until it is in the player's view (view 'plus': the player's cell and
its four neighbours, as in FrozenLake; '3x3': the 3 x 3 cells around the player). The walls, the floor and the box are always shown.
The picture is the game's own (gym_sokoban's rgb_array, 16 pixels a tile, as VAGEN gives it; `scale` enlarges it by an integer
factor); the prompt shows the room at the start and after each action, in order. The actions are the game's: UP, DOWN, LEFT, RIGHT (a step into the box pushes it), one each turn. The box on the target
wins; T_ACTIONS actions (VAGEN's evaluation budget: 5 turns of up to 3 actions). There is no answer line: the box on the target is
the answer.

The teacher's belief is exact: the target cells no view has excluded, all equally likely. Its policy pi* (Reliability.util of the
return: the box on the target after n actions is worth u(c(n), phi), the action limit u(c(T), 0)): a move is worth the return it
leads to (Belief.lookahead), an exact expectimax over the posterior to the end of the game: after each move the box on a
cell that may hold the target wins with its chance, else the view from the player's new cell shows the target (its cell is then
known) or excludes the cells it shows; with the target known, the return of its shortest solution (Ep.dist: exact, a search over
player and box; a dead box or past the limit: the floor). The game is at most T_ACTIONS actions, so the expectimax goes to its end
(not to the run's depth: with depth 2 and each candidate's solution at the leaf the greedy teacher stood still where a view or a
push had to come first, won 88% from start states). Its table of values depends only on (state, possible targets, time) and is
shared by the plans of an episode (a room's first plan ~27 ms on average, the later ones ~0.15 ms).
Before the fix (plearn.tasks.SK_GUESS_VALUE, --sk_guess_value 1: _guess_lookahead): with the target known, an action was worth the
time of the shortest solution after it; before that, the best of committing (pushing toward a target: its probability 1 / k as the
accuracy of a guess, with the time of the solution) and exploring (a walk that does not push, to a cell whose view shows candidates:
E[u] over 'the target is in view' and 'it is not', the rest again a guess). The game has no guess: a box on another cell only shows
that cell is not the target, and the search goes on, so log(1 / k) undervalued every plan that leaves candidates to be found later
(pushes above all; the views on the way and the box landing on the target counted for nothing) (the trainer's module text).
The belief line names the cells that may hold the target, 'Possible: target at B3, D4' ('Possible: any' at
the start), scored as a set.
"""
from __future__ import annotations
import copy, hashlib, math, re
from collections import deque
import numpy as np
from plearn.api.episode import carried
import plearn.tasks as _tasks                                        # SK_GUESS_VALUE

DIM, T_ACTIONS, MOVE_COST, MISS = 6, 15, 0.98, 50.0
BAND, VIEW = (1, 5), "plus"                                         # VAGEN's band; the player's cell and its neighbours
MODULUS, EVAL_BUCKET, TEST_SEEDS = 4, 0, range(20000, 20128)        # VAGEN's map partition and its evaluation seeds
PARTITION = {"train": "train", "validation": "eval"}                 # VAGEN's map_partition of each split (the test: none)
UP, DOWN, LEFT, RIGHT = 1, 2, 3, 4                                  # gym_sokoban's push actions (VAGEN's ACTION_LOOKUP)
ACTIONS = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT"}
STEP = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}


def room_key(fixed, state):
    """The generated room's sha256 (the bytes VAGEN hashes for its map partition): the key of a room."""
    a = lambda x: np.asarray(x, dtype="<i8", order="C").tobytes()
    return hashlib.sha256(a(fixed) + a(state)).digest()


def generate(seed, band=None, partition=None, avoid=()):
    """VAGEN's room for a seed: the loop of VAGEN's PatchedSokobanEnv.reset, with its own functions (benchmarks/vagen): set_seed
    around gym_sokoban's generate_room, the shortest solution (get_shortest_action_path, VAGEN's search depth 200), the
    min_solution_steps band, the map partition (_room_matches_partition) and a new seed by _next_retry_seed after a failed try.
    avoid: room keys never to give (training and validation avoid the test rooms); such a room is a failed try."""
    from gym_sokoban.envs.room_utils import generate_room
    from vagen.envs.sokoban.patch_sokoban_env import _next_retry_seed, _room_matches_partition, get_shortest_action_path
    from vagen.envs.sokoban.utils.seeding import set_seed
    for _ in range(10000):
        try:
            with set_seed(seed):
                fixed, state, _ = generate_room(dim=(DIM, DIM), num_steps=int(1.7 * (DIM + DIM)), num_boxes=1, second_player=False)
                L = len(get_shortest_action_path(fixed, state, MAX_DEPTH=200))
                if ((band is None or band[0] <= L <= band[1]) and _room_matches_partition(fixed, state, partition, MODULUS, EVAL_BUCKET)
                        and room_key(fixed, state) not in avoid):
                    return fixed, state
        except (RuntimeError, RuntimeWarning):
            pass
        seed = _next_retry_seed(seed)
    raise RuntimeError("no Sokoban room in the band")


_TEST_ROOMS = {}
def test_rooms(band):
    """The keys of the test rooms (VAGEN's evaluation seeds, no partition)."""
    if band not in _TEST_ROOMS: _TEST_ROOMS[band] = {room_key(*generate(s, band)) for s in TEST_SEEDS}
    return _TEST_ROOMS[band]


def name(cell): return f"{chr(65 + cell[1])}{cell[0] + 1}"


def window(cell, view="3x3"):
    """The cells the target shows from: the 3 x 3 cells around the player, or ('plus') its own cell and its four neighbours."""
    r, c = cell
    if view == "plus": return {(r, c), (r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
    return {(r + dr, c + dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1)}


class Graph:
    """The game's moves over (player, box) states of a room: a step moves the player, a step into the box pushes it when the cell
    beyond is floor; a step into a wall, or a blocked push, changes nothing."""
    def __init__(self, floor):
        self.floor = floor
    def free(self, p): return 0 <= p[0] < DIM and 0 <= p[1] < DIM and bool(self.floor[p])
    def step(self, s, a):
        (p, b), (dr, dc) = s, STEP[a]; q = (p[0] + dr, p[1] + dc)
        if not self.free(q): return s
        if q == b:
            nb = (b[0] + dr, b[1] + dc)
            return (q, nb) if self.free(nb) else s
        return (q, b)
    def reachable(self, s0):
        seen, q = {s0}, deque([s0])
        while q:
            s = q.popleft()
            for a in ACTIONS:
                n = self.step(s, a)
                if n not in seen: seen.add(n); q.append(n)
        return seen
    def to_goal(self, states, target):
        """Shortest numbers of actions from each state to the box on `target` (a backward search; missing: impossible)."""
        back = {}
        for s in states:
            for a in ACTIONS:
                n = self.step(s, a)
                if n != s: back.setdefault(n, []).append(s)
        dist = {s: 0 for s in states if s[1] == target}; q = deque(dist)
        while q:
            s = q.popleft()
            for prev in back.get(s, ()):
                if prev not in dist: dist[prev] = dist[s] + 1; q.append(prev)
        return dist
    def walks(self, s):
        """Moves of the player alone (the box stays) from state s to every cell: {cell: actions}."""
        (p, b) = s; dist = {p: 0}; q = deque([p])
        while q:
            c = q.popleft()
            for dr, dc in STEP.values():
                n = (c[0] + dr, c[1] + dc)
                if n not in dist and self.free(n) and n != b: dist[n] = dist[c] + 1; q.append(n)
        return dist


def rules_text(view=VIEW, actions=T_ACTIONS):
    near = "next to it (a diagonal neighbour too)" if view == "3x3" else "on it or right next to it (not diagonally)"
    return ("You play Sokoban in a room of 6 x 6 cells (columns A to F from the left, rows 1 to 6 from the top). Push the box onto the "
            f"target square. The target is hidden: it is one of the cells the box can be pushed to, each equally "
            f"likely, and it shows only when you stand {near}. UP, DOWN, LEFT and RIGHT move you one cell; a step into the box "
            f"pushes it, if the cell behind it is free. You have {actions} actions, one each turn.")


SYSTEM = ("You search for a hidden target and push a box onto it. Each turn, think, then reply with exactly two lines.\n"
          "Line 1: 'Possible: target at ' and the cells that may still hold the target, for example 'Possible: target at B3, D4', or "
          "'Possible: any' when no cell is excluded yet.\n"
          "Line 2: 'ACTION: UP', 'ACTION: DOWN', 'ACTION: LEFT' or 'ACTION: RIGHT'.")


class _GB:
    __slots__ = ("u", "n")
    def __init__(self, u, n): self.u, self.n = u, n
    def cls(self): return ("sokoban", min(self.n, 4))
    def U(self): return self.u


class Belief:
    __slots__ = ("ep", "alive", "t", "_k")
    def __init__(self, ep, alive, t):
        self.ep, self.alive, self.t = ep, alive, t; self._k = (id(ep), t, ep.state, frozenset(alive))
    def __hash__(self): return hash(self._k)
    def __eq__(self, o): return self._k == o._k
    def U(self): return 1.0 / len(self.alive)
    def identified(self): return len(self.alive) == 1
    def cls(self): return ("sokoban", min(len(self.alive), 4))
    def post(self): return {name(c): 1.0 / len(self.alive) for c in self.alive}
    def look_info(self, a):
        """--stall_cap: the expected drop of the target's entropy (nats) of move a, as _q splits the cells that may hold
        it: the box pushed onto one of them, or one of them in the view from the new cell, makes the target known; the others stay
        equally likely. 0 when the move shows none of them (a step into a wall too), and once the target is known."""
        ep = self.ep; A = frozenset(self.alive); k = len(A)
        if k <= 1: return 0.0
        s1 = ep.graph.step(ep.state, a); view = window(s1[0], ep.view)
        hidden = sum(1 for c in A - {s1[1]} if c not in view)
        return max(0.0, math.log(k) - (hidden / k * math.log(hidden) if hidden else 0.0))
    def lookahead(self, rel, lam, T, depth, acts):
        """Q(a): the return move a leads to (see the module text); SK_GUESS_VALUE: the old value, heading for a target as a guess."""
        if _tasks.SK_GUESS_VALUE: return self._guess_lookahead(rel, lam, T, depth, acts)
        cost = lambda n: math.exp(-lam * n / T); acc = rel.mean(_GB(1.0, 1))
        tab = tuple([rel.util(cost(n), acc) for n in range(T + 1)] + [rel.util(cost(T), 0.0)])   # the box on the target at n; T + 1: never
        ep = self.ep; vals = getattr(ep, "_vals", None)
        key = (ep.view, T, tab); memo = {} if vals is None else vals.get(key)   # V depends on nothing else: shared by the episode's
        if memo is None: vals.clear(); memo = vals[key] = {}                    # plans (one table: the latest accuracy and time cost)
        A = frozenset(self.alive)
        return {a: self._q(ep, tab, T, memo, ep.state, A, self.t, a) for a in acts}
    def _v(self, ep, tab, T, memo, s, A, t):
        """The best return from state s at time t with the target among A (each equally likely); with the target known, its exact
        shortest solution (Ep.dist; a dead box or past the action limit: the floor)."""
        if len(A) == 1:
            (c,) = A; L = ep.dist(c).get(s); return tab[T + 1 if L is None else min(t + L, T + 1)]
        if t >= T: return tab[T + 1]
        k = (s, A, t); v = memo.get(k)
        if v is None: v = memo[k] = max(self._q(ep, tab, T, memo, s, A, t, a) for a in ACTIONS)
        return v
    def _q(self, ep, tab, T, memo, s, A, t, a):
        """Move a from state s at time t: the box on a cell that may hold the target wins with its chance; otherwise the view from
        the new cell shows the target (its cell is then known) or excludes the cells it shows; then the best play after each."""
        s1 = ep.graph.step(s, a); t1 = t + 1; k = len(A); b1 = s1[1]
        if k == 1: return self._v(ep, tab, T, memo, s1, A, t1)
        v = tab[t1] / k if b1 in A else 0.0                                      # the box on the target: the game is won at t1
        rest = A - {b1}
        if not rest: return v
        view = window(s1[0], ep.view); hidden = frozenset(c for c in rest if c not in view)
        for c in rest:
            if c in view: v += self._v(ep, tab, T, memo, s1, frozenset((c,)), t1) / k
        if hidden: v += len(hidden) / k * self._v(ep, tab, T, memo, s1, hidden, t1)
        return v
    def _guess_lookahead(self, rel, lam, T, depth, acts):
        """Before the fix (SK_GUESS_VALUE): committing to a target valued as a guess among the candidates (see the module text)."""
        ep = self.ep; cost = lambda n: math.exp(-lam * n / T); out = {}
        def solve(state, n, c, acc):                                  # the box onto c from state at time n, with accuracy acc
            L = ep.dist(c).get(state)
            return rel.util(1.0, 0.0) if L is None or n + L > T else rel.util(cost(n + L), acc)
        def commit(state, n, cands):                                 # the best target to head for, each with its probability
            k = len(cands); return max(solve(state, n, c, rel.mean(_GB(1.0 / k, k))) for c in cands)
        for a in acts:
            s1 = ep.graph.step(ep.state, a); n1 = self.t + 1
            if self.identified():
                (c,) = tuple(self.alive); out[a] = solve(s1, n1, c, rel.mean(_GB(1.0, 1))); continue
            best = commit(s1, n1, self.alive)
            for cell, d in ep.graph.walks(s1).items():                # explore: walk (no push) to a cell whose view shows candidates
                inview = [c for c in self.alive if c in window(cell, ep.view) and c not in ep.seen_cells]
                if not inview or n1 + d > T: continue
                k = len(self.alive); s2 = (cell, s1[1]); rest = [c for c in self.alive if c not in inview]
                v = sum(solve(s2, n1 + d, c, rel.mean(_GB(1.0, 1))) for c in inview) / k
                if rest: v += len(rest) / k * commit(s2, n1 + d, rest)
                best = max(best, v)
            out[a] = best
        return out


def read_line(text):
    m = re.match(r"^\s*possible\s*:\s*(.*?)\s*\.?\s*$", str(text), re.I | re.S)
    if not m: return None
    body = m.group(1).strip()
    if re.fullmatch(r"(?:any|all|any cell|anywhere)", body, re.I): return {(r, c) for r in range(DIM) for c in range(DIM)}
    body = re.sub(r"^(?:the\s+)?target\s*(?:at|in|:)?\s*", "", body, flags=re.I)
    cells = re.findall(r"\b([A-Fa-f])\s*([1-6])\b", body)
    if not cells or re.sub(r"[A-Fa-f]\s*[1-6]|[\s,;]|and|or", "", body, flags=re.I): return None
    return {(int(r) - 1, ord(c.upper()) - 65) for c, r in cells}


def set_score(post, s, miss=MISS):
    pin = sum(post.get(name(c), 0.0) for c in s); return -pin * math.log(max(1, len(s))) - miss * (1.0 - pin)


class Ep:
    def __init__(self, spec, scale=1, band=BAND, view=VIEW):
        from gym_sokoban.envs.sokoban_env import SokobanEnv
        self.spec, self.scale, self.view = spec, int(scale), view
        split = spec[2] if len(spec) > 2 else "test"
        fixed, state = generate(int(spec[1]), band, PARTITION.get(split), test_rooms(band) if split != "test" else ())
        self.room = room_key(fixed, state)                                            # the generated room (before our target)
        floor = fixed != 0; self.graph = Graph(floor)
        p0 = tuple(int(v) for v in np.argwhere(state == 5)[0]); b0 = tuple(int(v) for v in np.argwhere((state == 4) | (state == 3))[0])
        self.state = (p0, b0); self.states = self.graph.reachable(self.state)
        self.candidates = sorted({s[1] for s in self.states} - {b0})
        self.target = self.candidates[np.random.default_rng(int(spec[1]) + 7919).integers(len(self.candidates))]
        fixed = np.where(fixed == 2, 1, fixed); fixed[self.target] = 2                # our target replaces the generator's
        state = np.where((state == 2) | (state == 3), 1, state); state[self.target] = 2; state[b0] = 4; state[p0] = 5   # gym_sokoban counts empty targets
        env = SokobanEnv(dim_room=(DIM, DIM), max_steps=10 ** 6, num_boxes=1, reset=False)
        env.room_fixed, env.room_state, env.player_position = fixed, state, np.array(p0)
        env.num_env_steps, env.reward_last, env.boxes_on_target = 0, 0, 0; self.env = env
        self.seen_cells = set(); self._dist = {}; self._vals = {}                 # Belief.lookahead's tables
        self.t, self.done, self.correct, self.turns_used, self.invalid, self.note, self.answer, self.log, self.won = 0, False, None, 0, 0, None, None, [], False
        self.see(); self.pictures = [self.picture()]                                # the room at the start, then after each action
    def dist(self, c):
        if c not in self._dist: self._dist[c] = self.graph.to_goal(self.states, c)
        return self._dist[c]
    def alive(self):
        if self.target in self.seen_cells: return {self.target}
        return {c for c in self.candidates if c not in self.seen_cells}
    def see(self): self.seen_cells |= window(self.state[0], self.view)
    def picture(self):
        from PIL import Image
        from gym_sokoban.envs.render_utils import room_to_rgb
        fixed, room = self.env.room_fixed.copy(), self.env.room_state.copy()
        if self.target not in self.seen_cells:                         # the target is drawn only once it has been seen
            fixed[self.target] = 1
            if room[self.target] == 2: room[self.target] = 1
        img = room_to_rgb(room, fixed)
        if self.scale > 1: img = np.kron(img, np.ones((self.scale, self.scale, 1), dtype=img.dtype))
        return Image.fromarray(img)


class Domain:
    name = "sokoban"
    images = True
    value_modes = ("accuracy", "log")

    def __init__(self, split="test", scale=1, band=BAND, view=VIEW, actions=T_ACTIONS, **_):
        self.split, self.scale, self.T = split, int(scale), int(actions); self.band = tuple(band) if band else None
        self.view = view; self.turns = self.T
        if split == "test" and _tasks.TEST_MOVES: self.T, self.turns = _tasks.TEST_MOVES, _tasks.TEST_TURNS   # plearn/tasks/__init__.py
        self.lam = self.T * math.log(1 / MOVE_COST)
        self.families = ["sokoban-hidden-target"]

    def sample(self, rng): return (self.families[0], rng.randrange(10 ** 6, 2 ** 31), "train")
    def eval_specs(self, n):
        base = {"test": 20000}.get(self.split, 10000); return [(self.families[0], base + i, self.split) for i in range(n)]
    def start(self, specs): return [Ep(tuple(s), self.scale, self.band, self.view) for s in specs]
    def close(self, eps): pass
    def family_of(self, e): return e.spec[0]

    def system_text(self, e): return SYSTEM
    def user_content(self, e, note=None):
        """The rules, then the room at the start and after each action, in order (a move that changed nothing too), so the prompt holds
        every cell already checked (with one picture of the room now, the checked cells would be only in the action list,
        and a move into a wall would leave no trace); the last belief line and the actions used."""
        parts, images = [{"type": "text", "text": rules_text(e.view, self.T)}], []
        for k, pic in enumerate(e.pictures):
            parts += [{"type": "text", "text": "\nThe room at the start: " if k == 0 else f"\nAfter action {k} ({e.log[k - 1]}): "}, {"type": "image"}]
            images.append(pic)
        parts.append({"type": "text", "text": carried(note) + f"\nActions used: {e.t} of {self.T}. Decide now."})
        return parts, images
    def _history(self, e): raise NotImplementedError("the game's observations are pictures")

    def look_strings(self, e): return {a: f"ACTION: {s}" for a, s in ACTIONS.items()} if not e.done and e.t < self.T else {}
    def look_name(self, a): return ACTIONS[a].lower()
    def answer_options(self, e): return []
    def commit_string(self, y): return f"ACTION: {y}"
    def canonical_action(self, text):
        t = " ".join(str(text).strip().rstrip(".").split()).upper()
        for s in ACTIONS.values():
            if t in (f"ACTION: {s}", s, f"ACTION: MOVE {s}", f"MOVE {s}", f"ACTION: PUSH {s}"): return f"ACTION: {s}"
        return " ".join(str(text).strip().split())
    def parse_action(self, e, text):
        t = self.canonical_action(text)
        for a, s in self.look_strings(e).items():
            if s == t: return ("look", a)
        return ("invalid", None)
    def do_look(self, e, a):
        _, _, done, _ = e.env.step(int(a))
        e.state = (tuple(int(v) for v in e.env.player_position), tuple(int(v) for v in np.argwhere((e.env.room_state == 4) | (e.env.room_state == 3))[0]))
        e.log.append(ACTIONS[int(a)].lower()); e.see(); e.pictures.append(e.picture())   # a move that changed nothing too
        if e.env.boxes_on_target == 1: e.won = True; e.done, e.correct = True, True
    def do_commit(self, e, y): return False
    def after_turn(self, e):
        e.turns_used += 1
        if not e.done and e.turns_used >= self.turns: e.done, e.correct = True, False

    def belief(self, e): return Belief(e, e.alive(), e.t)
    def freeze(self, B):
        """B with its game frozen at B's history: a plan keeps B, and the own turns of a history are scored
        after the game has gone on, so the lookahead of a stated line (decision_score) must read the agent's place and what it has
        seen at the history, not at the game's end. The plan made at the history is unchanged: it ran on the live game then."""
        s = copy.copy(B.ep); s.seen_cells = set(B.ep.seen_cells); s.log = list(B.ep.log); return Belief(s, B.alive, B.t)   # state: a tuple
    def label(self, e): return name(e.target)
    def answer_posterior(self, e): return self.belief(e).post()
    def answer_prob(self, B, y): return B.post().get(str(y).strip().upper(), 0.0)
    def state_text(self, e):
        B = self.belief(e); cells = sorted(B.alive)
        return "Possible: any" if len(cells) == len(e.candidates) else "Possible: target at " + ", ".join(name(c) for c in cells)
    def belief_note(self, e): return self.state_text(e)
    def belief_score(self, B, text, miss=MISS):
        s = read_line(text); return -miss if s is None else set_score(B.post(), s, miss)
    def belief_best(self, B, miss=MISS): return set_score(B.post(), set(B.alive), miss)
    def line_excess(self, B, text, exact):   # the share of the line's cells that the exact line excludes (--line_wide), both read by this reader
        s, x = read_line(text), read_line(exact); return len(s - x) / len(s) if s and x is not None else 0.0
    def line_belief(self, B, text):
        """The belief a line states, as the teacher's posterior (--line_score decision): the target cells it names among the
        level's candidates, those the evidence excluded too; None when it is not a belief line or names no candidate."""
        s = read_line(text)
        if s is None: return None
        alive = {c for c in B.ep.candidates if c in s}
        return Belief(B.ep, alive, B.t) if alive else None
    def read_exact(self, text): return read_line(text) is not None
    def anchor_support(self, text, answers, e=None):
        s = read_line(text); return {name(c) for c in s} if s else set(answers)
    def anchor_equal(self, a, b): x, y = read_line(a), read_line(b); return x is not None and x == y
    def anchor_answer(self, anchor, answers, e=None):
        s = read_line(anchor); return name(min(s)) if s else (answers[0] if answers else "")
    def extra_metrics(self, eps):
        if not eps: return {}
        return {"won": float(np.mean([e.won for e in eps])), "actions": float(np.mean([e.t for e in eps]))}


